const path = "[REDACTED: local Windows profile path]\\Desktop\\悉尼大学学习相关\\实习相关\\面试小问题\\project\\CertDesk-A-Multi-Tenant-Certificate-Admin-Console-";
const res = await tools.exec_command({cmd:String.raw`
$ErrorActionPreference = 'Stop'
$probe = [Net.Sockets.TcpListener]::new([Net.IPAddress]::Loopback, 0)
$probe.Start()
$checkPort = $probe.LocalEndpoint.Port
$probe.Stop()
$checkDirectory = Join-Path ([System.IO.Path]::GetTempPath()) ('certdesk-startup-' + [Guid]::NewGuid().ToString('N'))
$null = New-Item -ItemType Directory -Path $checkDirectory
$checkDb = Join-Path $checkDirectory 'smoke.sqlite3'
$checkStdout = Join-Path $checkDirectory 'stdout.log'
$checkStderr = Join-Path $checkDirectory 'stderr.log'
$checkProcess = $null
function Show-SydneyTime {
    [TimeZoneInfo]::ConvertTimeBySystemTimeZoneId([DateTimeOffset]::UtcNow, 'AUS Eastern Standard Time').ToString('o')
}
try {
    Write-Output ('Started ' + (Show-SydneyTime))
    Write-Output ('python run.py --port ' + $checkPort + ' --db "' + $checkDb + '"')
    $checkProcess = Start-Process -FilePath (Get-Command python).Source -ArgumentList @('run.py', '--port', $checkPort, '--db', ('"{0}"' -f $checkDb)) -WorkingDirectory (Get-Location).Path -WindowStyle Hidden -PassThru -RedirectStandardOutput $checkStdout -RedirectStandardError $checkStderr
    $base = 'http://127.0.0.1:' + $checkPort
    $deadline = [DateTime]::UtcNow.AddSeconds(15)
    $homeResponse = $null
    while (-not $homeResponse -and [DateTime]::UtcNow -lt $deadline) {
        if ($checkProcess.HasExited) { throw 'Launcher exited before becoming ready' }
        try {
            $homeResponse = Invoke-WebRequest -Uri "$base/" -TimeoutSec 2
        } catch {
            Start-Sleep -Milliseconds 200
        }
    }
    if (-not $homeResponse -or $homeResponse.StatusCode -ne 200 -or $homeResponse.Content -notmatch '<div id="app"' -or $homeResponse.Content -notmatch '/vendor/vue\.global\.prod\.js') { throw 'SPA HTML check failed' }
    $vueResponse = Invoke-WebRequest -Uri "$base/vendor/vue.global.prod.js" -TimeoutSec 2
    if ($vueResponse.StatusCode -ne 200 -or $vueResponse.RawContentLength -lt 100000) { throw 'Vue asset check failed' }
    $apiResponse = Invoke-WebRequest -Uri "$base/api/courses" -Headers @{'X-Actor'='alice@east.test'} -TimeoutSec 2
    if ($apiResponse.StatusCode -ne 200 -or $apiResponse.Content -notmatch 'Safety 101' -or $apiResponse.Content -notmatch 'First Aid') { throw 'Demo API check failed' }
    if (-not (Test-Path -LiteralPath $checkDb -PathType Leaf)) { throw 'Database was not initialized' }
    Write-Output ("PASS GET /: $($homeResponse.StatusCode), CertDesk SPA mount and vendored Vue script")
    Write-Output ("PASS GET /vendor/vue.global.prod.js: $($vueResponse.StatusCode), $($vueResponse.RawContentLength) bytes")
    Write-Output ("PASS GET /api/courses as Alice: $($apiResponse.StatusCode), $($apiResponse.Content)")
    Write-Output ('Verified ' + (Show-SydneyTime))
} finally {
    if ($checkProcess -and -not $checkProcess.HasExited) {
        taskkill.exe /PID $checkProcess.Id /T /F | Out-Host
        $checkProcess.WaitForExit(5000) | Out-Null
    }
    if (Test-Path -LiteralPath $checkStdout -PathType Leaf) { Get-Content -LiteralPath $checkStdout }
    if (Test-Path -LiteralPath $checkStderr -PathType Leaf) { Get-Content -LiteralPath $checkStderr }
    foreach ($checkFile in @($checkStdout, $checkStderr, $checkDb, "$checkDb-wal", "$checkDb-shm", "$checkDb-journal")) {
        if (Test-Path -LiteralPath $checkFile -PathType Leaf) { Remove-Item -LiteralPath $checkFile -Force }
    }
    Remove-Item -LiteralPath $checkDirectory
    Write-Output ('Cleaned up ' + (Show-SydneyTime))
}
`,workdir:path,max_output_tokens:3500,yield_time_ms:1000});
text(res)

